#include <math.h>
#include <stdio.h>
#include <string.h>
#include "busfx.h"
#include "smc_fx_map.h"

static int failures;
#define BPM 120.0f
#define T0 0u

static void expect(int cond, const char *msg)
{
    if (!cond) {
        fprintf(stderr, "FAIL %s\n", msg);
        failures++;
    }
}

static float rms(const float *x, int n)
{
    double a = 0;
    int i;
    for (i = 0; i < n; i++)
        a += (double)x[i] * (double)x[i];
    return (float)sqrt(a / n);
}

static float max_abs(const float *x, int n)
{
    float m = 0;
    int i;
    for (i = 0; i < n; i++) {
        float a = x[i] < 0 ? -x[i] : x[i];
        if (a > m)
            m = a;
    }
    return m;
}

static void fill_sine(float *x, int n, float hz, float amp)
{
    int i;
    for (i = 0; i < n; i++)
        x[i] = amp * sinf(2.0f * 3.14159265f * hz * (float)i / 44100.0f);
}

static void test_wire(void)
{
    busfx_t s;
    float x[128], y[128];
    int i;
    busfx_init(&s);
    for (i = 0; i < 128; i++)
        x[i] = y[i] = ((i * 17) % 50) * 0.01f - 0.25f;
    busfx_apply(&s, 0, 0, y, 0, 0, 0, 1, 128, 127.0f, 0, BFX_GATE, 128, 128, BPM, T0);
    for (i = 0; i < 128; i++)
        if (y[i] != x[i])
            break;
    expect(i == 128, "open cutoff is a wire");
}

static void test_bpm_range(void)
{
    expect(busfx_sp16(10.0f) == busfx_sp16(20.0f), "BPM floors at 20");
    expect(busfx_sp16(400.0f) == busfx_sp16(300.0f), "BPM caps at 300");
}

static void test_main_throw(void)
{
    expect(busfx_send(BFX_SEND_NOM, 1, BFX_REV, BFX_REV) == 1.0f, "RVB rev throw opens");
    expect(busfx_send(BFX_SEND_NOM, 0, BFX_REV, BFX_REV) == BFX_SEND_NOM, "RVB rev throw releases");
    expect(busfx_send(BFX_SEND_NOM, 1, BFX_DLY, BFX_DLY) == 1.0f, "DLY throw opens");
}

static void test_stutter_stereo(void)
{
    busfx_t s;
    busfx_stut_t stut;
    float l[2048], r[2048];
    int i;
    busfx_init(&s);
    busfx_stut_init(&stut);
    for (i = 0; i < 2048; i++) {
        l[i] = 1.0f;
        r[i] = 0.0f;
    }
    busfx_apply(&s, &stut, 0, l, r, 0, 0, 2, 2048, 127.0f, 1, BFX_STUT, 2048, 2048, BPM, 0u);
    expect(max_abs(r, 2048) < 0.08f, "stutter right stays dry when left-only input");
    expect(max_abs(l, 2048) > 0.2f, "stutter left still moves");
}

static void test_settling(void)
{
    busfx_t s;
    float x[512];
    busfx_init(&s);
    fill_sine(x, 512, 200.0f, 0.5f);
    busfx_apply(&s, 0, 0, x, 0, 0, 0, 1, 256, 127.0f, 1, BFX_HP, 256, 256, BPM, T0);
    expect(busfx_settling(&s), "HP hold leaves filters settling");
    busfx_apply(&s, 0, 0, x + 256, 0, 0, 0, 1, 256, 127.0f, 0, BFX_HP, 256, 256, BPM, T0);
    expect(busfx_settling(&s), "release keeps HP settling");
}

static void test_rhythm_gate(void)
{
    busfx_t s;
    float x[16384], dry[16384];
    uint32_t sp16 = busfx_sp16(BPM), sp8 = busfx_sp8(BPM);
    busfx_init(&s);
    fill_sine(x, 16384, 110.0f, 0.5f);
    memcpy(dry, x, sizeof dry);
    busfx_apply(&s, 0, 0, x, 0, 0, 0, 1, 16384, 127.0f, 1, BFX_GATE16, 16384, 16384, BPM, T0);
    expect(rms(x + 12000, 4096) < rms(dry + 12000, 4096) * 0.82f, "16th gate thins a held tone");
    expect(busfx_rhythm_target(BFX_GATE16, BPM, 0) == 1.0f, "16th gate opens at phase zero");
    expect(busfx_rhythm_target(BFX_GATE16, BPM, (sp16 * 3u) / 4u) == 0.0f, "16th gate closes late in division");
    expect(busfx_rhythm_target(BFX_GATE8, BPM, 0) == 1.0f &&
               busfx_rhythm_target(BFX_GATE8, BPM, (sp8 * 3u) / 4u) == 0.0f,
           "8th gate toggles at tempo");
}

static void test_map(void)
{
    int page, bus, k;
    expect(SMCFX_N == 8, "eight momentary strips");
    expect(SMCFX_NOTE[SMCFX_303B] == 27 && SMCFX_PART[3] == 3, "303B is note 27 on PART_303B");
    expect(SMCFX_NOTE[SMCFX_RVB] == 29 && SMCFX_NOTE[SMCFX_MDLY] == 30 && SMCFX_NOTE[SMCFX_FLT] == 31,
           "main strips use SELECT notes 29-31");
    for (bus = 0; bus < SMCFX_N; bus++) {
        for (k = 0; k < SMCFX_SUIT_N[bus]; k++)
            expect(SMCFX_SUIT[bus][k] < SMCFX_NFX, "suit entries are valid effects");
        if (bus == SMCFX_RVB)
            expect(SMCFX_SUIT[bus][1] == SMCFX_GATE8 && SMCFX_SUIT[bus][0] == SMCFX_REV,
                   "RVB lists throw then tempo gates");
    }
    for (page = 0; page < SMCFX_NPAGE; page++)
        for (bus = 0; bus < SMCFX_N; bus++)
            expect(smcfx_suit_ok(bus, SMCFX_PAGE[page][bus]), "preset pages only assign suited effects");
    expect(smcfx_cycle(SMCFX_RVB, SMCFX_REV) == SMCFX_GATE8, "RVB cycles to 8th gate after throw");
    expect(smcfx_bus(27) == SMCFX_303B && smcfx_bus(31) == SMCFX_FLT, "all eight SELECT notes map");
}

int main(void)
{
    test_wire();
    test_bpm_range();
    test_main_throw();
    test_stutter_stereo();
    test_settling();
    test_rhythm_gate();
    test_map();
    if (failures) {
        fprintf(stderr, "%d failed\n", failures);
        return 1;
    }
    puts("PASS smc fx: BPM range, throws, stutter stereo, settling, rhythm, eight-bus map");
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only
 * Regression: an accepted new LE connection is a new BLE-MIDI epoch.
 * Queued Note Off and outgoing SysEx from before that link must never replay.
 * Native full-source command (when the exact Git root is available):
 *   cc -std=c99 -O1 -g -Wall -Wextra -Werror -Ifirmware/src/ble \
 *     tests/host/ble_link_epoch_reset_test.c firmware/src/ble/ble_midi_host.c \
 *     -o /tmp/ble_link_epoch_reset_test && /tmp/ble_link_epoch_reset_test
 */
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include "ble_midi_host.h"
static unsigned checks, failures;
#define CHECK(x) do { ++checks; if (!(x)) { ++failures; fprintf(stderr,"FAIL line %u: %s\n",(unsigned)__LINE__,#x); } } while (0)
static int send_packet(uint8_t type, const uint8_t *p, uint16_t n, void *ctx)
{ (void)type; (void)p; (void)n; (void)ctx; return 0; }
static void setup(bleh_t *h)
{
    bleh_init(h, send_packet, NULL, "X0X37", NULL);
    h->state = BLEH_ADVERTISING;
    h->acl_total = 4;
}
static void dirty(bleh_t *h)
{
    h->q_r = 3; h->q_w = 6; /* queued Note Off and other messages */
    h->sx_on = 3; h->sx_len = 5; h->sx_pos = 2;
    h->cccd[0] = 1; h->att_rsp_len = 3;
    h->rx_on = 1; h->in_r = 3; h->in_w = 4; h->in_running = 0x90;
    h->cpu_state = 1;
}
static void accepted(bleh_t *h, unsigned conn)
{
    /* LE Meta Event, legacy Connection Complete: success, handle, peripheral role. */
    uint8_t event[7] = {0x3e, 5, 1, 0, (uint8_t)conn, (uint8_t)(conn >> 8), 1};
    bleh_rx(h, BLEH_H4_EVT, event, sizeof event);
}
static void test_new_advertising_link(void)
{
    bleh_t h;
    setup(&h); dirty(&h);
    accepted(&h, 0x0041);
    CHECK(h.state == BLEH_CONNECTED);
    CHECK(h.conn == 0x0041);
    CHECK(h.q_r == h.q_w); /* must not send Note Off from before link */
    CHECK(h.sx_on == 0);    /* must not restart old SysEx fragment */
    CHECK(h.sx_len == 0 && h.sx_pos == 0);
    CHECK(h.cccd[0] == 0 && h.att_rsp_len == 0);
    CHECK(h.rx_on == 0 && h.in_r == h.in_w);
    CHECK(h.cpu_state == 0);
}
static void test_new_handle_replaces_old_connection(void)
{
    bleh_t h;
    setup(&h); h.state = BLEH_CONNECTED; h.conn = 0x0040; dirty(&h);
    accepted(&h, 0x0042);
    CHECK(h.conn == 0x0042);
    CHECK(h.q_r == h.q_w);
    CHECK(h.sx_on == 0 && h.sx_len == 0 && h.sx_pos == 0);
}
static void test_failed_connection_does_not_erase_outbox(void)
{
    bleh_t h;
    const uint8_t failed[] = {0x3e, 5, 1, 1, 0x43, 0, 1};
    setup(&h); dirty(&h);
    bleh_rx(&h, BLEH_H4_EVT, failed, sizeof failed);
    CHECK(h.state == BLEH_ADVERTISING);
    CHECK(h.q_r == 3 && h.q_w == 6);
    CHECK(h.sx_on == 3 && h.sx_len == 5 && h.sx_pos == 2);
}
static void test_disconnection_and_unrelated_handle(void)
{
    bleh_t h;
    const uint8_t unrelated[] = {0x05, 4, 0, 0x43, 0, 0x13};
    const uint8_t matched[] = {0x05, 4, 0, 0x41, 0, 0x13};
    setup(&h); h.state = BLEH_CONNECTED; h.conn = 0x41; dirty(&h);
    bleh_rx(&h, BLEH_H4_EVT, unrelated, sizeof unrelated);
    CHECK(h.state == BLEH_CONNECTED);
    CHECK(h.q_r == 3 && h.sx_on == 3);
    bleh_rx(&h, BLEH_H4_EVT, matched, sizeof matched);
    CHECK(h.state == BLEH_ADVERTISING);
    CHECK(h.q_r == h.q_w && h.sx_on == 0);
}
static void test_truncated_event_ignored(void)
{
    bleh_t h;
    const uint8_t truncated[] = {0x3e, 5, 1, 0, 0x44};
    setup(&h); dirty(&h);
    bleh_rx(&h, BLEH_H4_EVT, truncated, sizeof truncated);
    CHECK(h.state == BLEH_ADVERTISING);
    CHECK(h.q_r == 3 && h.q_w == 6 && h.sx_on == 3);
}
int main(void)
{
    test_new_advertising_link();
    test_new_handle_replaces_old_connection();
    test_failed_connection_does_not_erase_outbox();
    test_disconnection_and_unrelated_handle();
    test_truncated_event_ignored();
    printf("BLE link-epoch reset: %u checks, %u failures\n", checks, failures);
    return failures ? 1 : 0;
}
